package org.fen.fen.recuperacaosenha;
import org.fen.fen.controller.SolicitacaoRecuperacaoSenhaController; import org.fen.fen.domain.StatusSolicitacaoRecuperacaoSenha; import org.fen.fen.error.ApiExceptionHandler; import org.fen.fen.recuperacaosenha.dto.*; import org.fen.fen.service.SolicitacaoRecuperacaoSenhaService; import org.junit.jupiter.api.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import java.time.LocalDateTime; import java.util.UUID; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class SolicitacaoRecuperacaoSenhaControllerTest { MockMvc mvc; SolicitacaoRecuperacaoSenhaService service; UUID id=UUID.randomUUID(); @BeforeEach void setup(){service=mock(SolicitacaoRecuperacaoSenhaService.class);mvc=MockMvcBuilders.standaloneSetup(new SolicitacaoRecuperacaoSenhaController(service)).setControllerAdvice(new ApiExceptionHandler()).build();}
@Test void criaSemExporCredencial()throws Exception{when(service.criar(any())).thenReturn(new SolicitacaoRecuperacaoSenhaResponse(id,"a@fen.br",StatusSolicitacaoRecuperacaoSenha.PENDENTE,LocalDateTime.now()));mvc.perform(post("/api/recuperacoes-senha").contentType("application/json").content("{\"email\":\"a@fen.br\",\"novaSenha\":\"senhaNova1\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.novaSenha").doesNotExist());}
@Test void exigeAdminParaAprovar(){PreAuthorize a=java.util.Arrays.stream(SolicitacaoRecuperacaoSenhaController.class.getDeclaredMethods()).map(m->m.getAnnotation(PreAuthorize.class)).filter(java.util.Objects::nonNull).findFirst().orElseThrow();assertThat(a.value()).isEqualTo("hasRole('ADMIN')");}}
